  service: DatasetReleaseService,
): Router {
  const router = Router();
  const authenticate = requireAuthentication(verifyAccessToken, synchronizeAccount);

  router.post(
    '/admin/dataset-releases',
    authenticate,
    requireAdministrator(),
    (request, response) => {
      const parsed = createDatasetReleaseSchema.safeParse(request.body);
      if (!parsed.success) {
        response
          .status(400)
          .json({ error: { code: 'VALIDATION_FAILED', message: 'The request is invalid.' } });
        return;
      }
      void service
        .createRelease(parsed.data)
        .then((release) => response.status(201).json({ data: release }));
    },
  );

  router.get('/dataset-releases', (_request, response) => {
    void service.listReleases().then((releases) => response.status(200).json({ data: releases }));
  });

  router.get('/dataset-releases/:version', (request, response) => {
    const version = datasetReleaseVersionSchema.safeParse(request.params.version);
    if (!version.success) {
      response
        .status(404)
        .json({ error: { code: 'NOT_FOUND', message: 'Dataset release not found.' } });
      return;
    }
    void service.getRelease(version.data).then((release) => {
      if (!release) {
        response
          .status(404)
          .json({ error: { code: 'NOT_FOUND', message: 'Dataset release not found.' } });
        return;
      }
      response.status(200).json({ data: release });
    });
  });

  router.get('/dataset-releases/:version/artifact.json', (request, response) => {
    const version = datasetReleaseVersionSchema.safeParse(request.params.version);
    if (!version.success) {
      response
        .status(404)
        .json({ error: { code: 'NOT_FOUND', message: 'Dataset release artifact not found.' } });
      return;
    }
    void service.getArtifact(version.data).then((artifact) => {
      if (!artifact) {
        response
          .status(404)
          .json({ error: { code: 'NOT_FOUND', message: 'Dataset release artifact not found.' } });
        return;
      }
      response
        .type('application/json')
        .attachment(`dataset-release-${version.data}.json`)
        .send(artifact);
    });
  });

  return router;
}
import { Navigate, Route, Routes } from 'react-router-dom';
import { PublicShell } from './components/PublicShell';
import { HomePage } from './features/home/HomePage';
import {
  CompetitionDetailPage,
  CompetitionsPage,
  CompetitorDetailPage,
  CompetitorsPage,
  FixtureDetailPage,
  FixturesPage,
  NotFoundPage,
  ParticipantDetailPage,
  ParticipantsPage,
  SeasonDetailPage,
  SeasonsPage,
} from './pages/PublicBrowsePages';
import {
  AccountPage,
  AuthenticationCallbackPage,
  AuthenticationPage,
} from './features/auth/AuthPages';
import { SubmissionPage } from './features/submissions/SubmissionPage';
import { BatchReportsPage } from './features/submissions/BatchReportsPage';
import {
  FixtureStatisticDetailPage,
  FixtureStatisticsPage,
} from './features/statistics/StatisticsPages';
import { AdminUsersPage } from './features/admin/AdminUsersPage';
import { BatchReviewWorkspacePage } from './features/reviews/BatchReviewWorkspacePage';
import {
  DatasetReleaseCataloguePage,
  DatasetReleaseDetailPage,
} from './features/dataset-releases/DatasetReleasePages';

export function PublicApp() {
  return (
    <PublicShell>
      <Routes>
        <Route path="/" element={<HomePage />} />

        <Route path="/competitions" element={<CompetitionsPage />} />
        <Route path="/competitions/:competitionId" element={<CompetitionDetailPage />} />

        <Route path="/seasons" element={<SeasonsPage />} />
        <Route path="/seasons/:seasonId" element={<SeasonDetailPage />} />

        <Route path="/fixtures" element={<FixturesPage />} />
        <Route path="/fixtures/:fixtureId" element={<FixtureDetailPage />} />
        <Route path="/fixtures/:fixtureId/statistics" element={<FixtureStatisticsPage />} />
        <Route
          path="/fixtures/:fixtureId/statistics/:statisticId"
          element={<FixtureStatisticDetailPage />}
        />

        <Route path="/competitors" element={<CompetitorsPage />} />
        <Route path="/competitors/:competitorId" element={<CompetitorDetailPage />} />

        <Route path="/participants" element={<ParticipantsPage />} />
        <Route path="/participants/:participantId" element={<ParticipantDetailPage />} />

        <Route path="/dataset-releases" element={<DatasetReleaseCataloguePage />} />
        <Route path="/dataset-releases/:version" element={<DatasetReleaseDetailPage />} />

        <Route path="/sign-in" element={<AuthenticationPage />} />
        <Route path="/auth/callback" element={<AuthenticationCallbackPage />} />
        <Route path="/account" element={<AccountPage />} />
        <Route path="/submissions/new" element={<SubmissionPage />} />
        <Route
          path="/submissions/batches/new"
          element={<Navigate to="/submissions/new" replace />}
        />
        <Route path="/submissions/batches" element={<BatchReportsPage />} />
        <Route path="/submissions/batches/:batchReference" element={<BatchReportsPage />} />
        <Route path="/admin/users" element={<AdminUsersPage />} />
        <Route path="/reviews/batches" element={<BatchReviewWorkspacePage />} />
        <Route path="/reviews/batches/:batchReference" element={<BatchReviewWorkspacePage />} />

        <Route path="*" element={<NotFoundPage />} />
      </Routes>
    </PublicShell>
  );
}

function App() {
  return <PublicApp />;
}

export default App;
import { useState, type ReactNode } from 'react';
import { Link, NavLink, useNavigate } from 'react-router-dom';
import { useAuth } from '../features/auth/AuthProvider';
import { ThemeToggle } from './ThemeToggle';

interface PublicShellProps {
  children: ReactNode;
}

function BrandWordmark() {
  return (
    <span className="brand-wordmark">
      <img
        className="brand-wordmark__image brand-asset--day"
        src="/brand/statsthegame-wordmark-light.svg"
        alt="Stat'sTheGame"
      />
      <img
        className="brand-wordmark__image brand-asset--night"
        src="/brand/statsthegame-wordmark-dark.svg"
        alt="Stat'sTheGame"
      />
    </span>
  );
}

function AuthenticationNavigation() {
  const { isAuthenticated, isLoading, signOut } = useAuth();
  const navigate = useNavigate();
  const [isSigningOut, setIsSigningOut] = useState(false);
  const [signOutError, setSignOutError] = useState<string | null>(null);

  async function handleSignOut() {
    setIsSigningOut(true);
    setSignOutError(null);

    try {
      await signOut();
      navigate('/', { replace: true });
    } catch {
      setSignOutError('We could not sign you out. Please try again.');
    } finally {
      setIsSigningOut(false);
    }
  }

  if (isLoading) {
    return (
      <p className="auth-navigation__status" role="status">
        Checking accountâ€¦
      </p>
    );
  }

  return (
    <div className="auth-navigation-wrap">
      <nav className="auth-navigation" aria-label="Account">
        {isAuthenticated ? (
          <>
            <NavLink to="/account">Account</NavLink>
            <button type="button" onClick={handleSignOut} disabled={isSigningOut}>
              {isSigningOut ? 'Signing Outâ€¦' : 'Sign Out'}
            </button>
          </>
        ) : (
          <NavLink to="/sign-in">Login or Sign up</NavLink>
        )}
      </nav>
      {signOutError ? (
        <p className="auth-navigation__error" role="alert">
          {signOutError}
        </p>
      ) : null}
    </div>
  );
}

export function PublicShell({ children }: PublicShellProps) {
  return (
    <div className="public-shell">
      <a className="skip-link" href="#main-content">
        Skip to main content
      </a>

      <header className="site-header">
        <div className="site-header__inner">
          <Link className="brand-link" to="/" aria-label="Stat'sTheGame home">
            <BrandWordmark />
          </Link>
          <nav aria-label="Public records" className="site-navigation">
            <NavLink to="/competitions">Competitions</NavLink>
            <NavLink to="/seasons">Seasons</NavLink>
            <NavLink to="/fixtures">Fixtures</NavLink>
            <NavLink to="/competitors">Teams</NavLink>
            <NavLink to="/participants">Players</NavLink>
            <NavLink to="/dataset-releases">Downloads</NavLink>
          </nav>
          <div className="site-header__controls">
            <AuthenticationNavigation />
            <ThemeToggle />
          </div>
        </div>
      </header>

      <main id="main-content">{children}</main>

      <footer className="site-footer">
        <div className="site-footer__inner">
          <BrandWordmark />
          <p>The game, measured ball by ball.</p>
        </div>
      </footer>
    </div>
  );
}

