import { z } from 'zod';

import { apiDateTimeSchema, apiIdentifierSchema, createResourceResponseSchema } from './api';

export const DATASET_RELEASE_FORMAT_VERSION = '1.0' as const;

export const datasetReleaseVersionSchema = z
  .string()
  .trim()
  .regex(/^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$/, 'Use a stable release version.');

export const createDatasetReleaseSchema = z
  .object({
    version: datasetReleaseVersionSchema,
  })
  .strict();

export const datasetReleaseFieldSchema = z
  .object({
    name: z.string().min(1),
    description: z.string().min(1),
  })
  .strict();

export const datasetReleaseSchema = z
  .object({
    releaseId: apiIdentifierSchema,
    version: datasetReleaseVersionSchema,
    createdAt: apiDateTimeSchema,
    formatVersion: z.literal(DATASET_RELEASE_FORMAT_VERSION),
    scope: z.literal('published-accepted-deliveries'),
    eventCount: z.number().int().nonnegative(),
    checksum: z.string().regex(/^[a-f0-9]{64}$/),
    fields: z.array(datasetReleaseFieldSchema),
  })
  .strict();

export const datasetReleaseResponseSchema = createResourceResponseSchema(datasetReleaseSchema);
export const datasetReleaseCollectionResponseSchema = z
  .object({
    data: z.array(datasetReleaseSchema),
  })
  .strict();

export type CreateDatasetRelease = z.infer<typeof createDatasetReleaseSchema>;
export type DatasetRelease = z.infer<typeof datasetReleaseSchema>;
import type { DatasetRelease } from '@sport-analytics/contracts';
import { useCallback } from 'react';
import { Link, useParams } from 'react-router-dom';

import { datasetReleaseArtifactUrl, publicReadApi } from '../../api/public-read';
import {
  DetailError,
  DetailLayout,
  DetailLoading,
  RecordFact,
  RecordFacts,
} from '../browse/RecordDetail';
import { usePublicData } from '../browse/usePublicData';

function formatCreationTime(value: string): string {
  return new Intl.DateTimeFormat('en-ZA', {
    dateStyle: 'long',
    timeStyle: 'short',
  }).format(new Date(value));
}

function scopeLabel(scope: DatasetRelease['scope']): string {
  return scope === 'published-accepted-deliveries' ? 'Published accepted deliveries' : scope;
}

export function DatasetReleaseCataloguePage() {
  const load = useCallback((signal: AbortSignal) => publicReadApi.listDatasetReleases(signal), []);
  const state = usePublicData(load, 'dataset-releases');

  return (
    <section className="release-page content-boundary">
      <header className="page-heading">
        <p className="eyebrow">Data downloads</p>
        <h1>Dataset releases</h1>
        <p>
          Discover immutable snapshots of published cricket data, review their scope and schema, and
          verify every download with its SHA-256 checksum.
        </p>
      </header>

      {state.status === 'loading' ? (
        <div className="state-message" role="status">
          <h3>Loading dataset releases</h3>
          <p>The available snapshots are being requested from the Sport Analytics API.</p>
        </div>
      ) : null}

      {state.status === 'error' ? (
        <div className="state-message state-message--error" role="alert">
          <h3>Dataset releases could not be loaded</h3>
          <p>{state.error.message}</p>
          <button className="button button--secondary" onClick={state.reload} type="button">
            Try again
          </button>
        </div>
      ) : null}

      {state.status === 'ready' && state.data.data.length === 0 ? (
        <div className="state-message">
          <h3>No dataset releases are available</h3>
          <p>Published snapshots will appear here when an administrator creates one.</p>
        </div>
      ) : null}

      {state.status === 'ready' && state.data.data.length > 0 ? (
        <div className="release-catalogue" aria-live="polite">
          <div className="results-heading">
            <h2>Available releases</h2>
            <p>{state.data.data.length} immutable snapshots</p>
          </div>
          <ul className="release-list">
            {state.data.data.map((release) => (
              <li key={release.releaseId}>
                <div>
                  <p className="eyebrow">Release {release.version}</p>
                  <h3>
                    <Link to={`/dataset-releases/${encodeURIComponent(release.version)}`}>
                      Dataset {release.version}
                    </Link>
                  </h3>
                  <p>{scopeLabel(release.scope)}</p>
                </div>
                <dl>
                  <div>
                    <dt>Created</dt>
                    <dd>{formatCreationTime(release.createdAt)}</dd>
                  </div>
                  <div>
                    <dt>Events</dt>
                    <dd>{release.eventCount.toLocaleString('en-ZA')}</dd>
                  </div>
                  <div>
                    <dt>Format</dt>
                    <dd>{release.formatVersion}</dd>
                  </div>
                </dl>
              </li>
            ))}
          </ul>
        </div>
      ) : null}
    </section>
  );
}

export function DatasetReleaseDetailPage() {
  const { version = '' } = useParams();
  const load = useCallback(
    (signal: AbortSignal) => publicReadApi.getDatasetRelease(version, signal),
    [version],
  );
  const state = usePublicData(load, version);

  if (state.status === 'loading') {
    return <DetailLoading label="dataset release" />;
  }

  if (state.status === 'error') {
    return <DetailError error={state.error} label="Dataset release" reload={state.reload} />;
  }

  const release = state.data.data;

  return (
    <DetailLayout
      backLabel="dataset releases"
      backTo="/dataset-releases"
      eyebrow="Immutable snapshot"
      title={`Dataset ${release.version}`}
    >
      <p className="release-summary">
        This release contains {release.eventCount.toLocaleString('en-ZA')} published accepted
        deliveries. Retain the checksum with your analysis to verify the downloaded bytes.
      </p>
      <RecordFacts>
        <RecordFact label="Created" value={formatCreationTime(release.createdAt)} />
        <RecordFact label="Scope" value={scopeLabel(release.scope)} />
        <RecordFact label="Format version" value={release.formatVersion} />
        <RecordFact label="Event count" value={release.eventCount.toLocaleString('en-ZA')} />
      </RecordFacts>

      <section className="release-download" aria-labelledby="release-download-heading">
        <h2 id="release-download-heading">Download and verify</h2>
        <p>
          Download the canonical JSON artefact. Calculate its SHA-256 digest and compare it with the
          published checksum below.
        </p>
        <a
          className="button button--primary"
          download={`dataset-release-${release.version}.json`}
          href={datasetReleaseArtifactUrl(release.version)}
        >
          Download JSON artefact
        </a>
        <dl className="release-checksum">
          <div>
            <dt>SHA-256 checksum</dt>
            <dd>
              <code>{release.checksum}</code>
            </dd>
          </div>
        </dl>
      </section>

      <section className="release-schema" aria-labelledby="release-schema-heading">
        <h2 id="release-schema-heading">Schema and fields</h2>
        <p>The artefact includes these documented fields for every delivery event.</p>
        <dl>
          {release.fields.map((field) => (
            <div key={field.name}>
              <dt>
                <code>{field.name}</code>
              </dt>
              <dd>{field.description}</dd>
            </div>
          ))}
        </dl>
      </section>
    </DetailLayout>
  );
}
import { fireEvent, render, screen, waitFor, within } from '@testing-library/react';
import { MemoryRouter, Route, Routes } from 'react-router-dom';
import { afterEach, describe, expect, it, vi } from 'vitest';

import { DatasetReleaseCataloguePage, DatasetReleaseDetailPage } from './DatasetReleasePages';

const release = {
  releaseId: '01234567-89ab-cdef-0123-456789abcdef',
  version: '2026.09.1',
  createdAt: '2026-09-09T10:00:00.000Z',
  formatVersion: '1.0',
  scope: 'published-accepted-deliveries',
  eventCount: 1234,
  checksum: 'a'.repeat(64),
  fields: [
    { name: 'eventId', description: 'Stable identifier of the accepted delivery revision.' },
    { name: 'fixtureId', description: 'Fixture containing the delivery.' },
  ],
};

function response(status: number, body: unknown): Response {
  return {
    ok: status >= 200 && status < 300,
    status,
    json: vi.fn().mockResolvedValue(body),
  } as unknown as Response;
}

function renderRoute(path: string) {
  return render(
    <MemoryRouter initialEntries={[path]}>
      <Routes>
        <Route path="/dataset-releases" element={<DatasetReleaseCataloguePage />} />
        <Route path="/dataset-releases/:version" element={<DatasetReleaseDetailPage />} />
      </Routes>
    </MemoryRouter>,
  );
}

describe('dataset release pages', () => {
  afterEach(() => {
    vi.restoreAllMocks();
    vi.unstubAllGlobals();
  });

  it('lists available releases with useful scope and creation metadata', async () => {
    vi.stubGlobal('fetch', vi.fn().mockResolvedValue(response(200, { data: [release] })));

    renderRoute('/dataset-releases');

    expect(await screen.findByRole('heading', { name: 'Available releases' })).toBeInTheDocument();
    const releaseLink = screen.getByRole('link', { name: 'Dataset 2026.09.1' });
    expect(releaseLink).toHaveAttribute('href', '/dataset-releases/2026.09.1');
    expect(screen.getByText('Published accepted deliveries')).toBeInTheDocument();
    expect(screen.getByText('1 234')).toBeInTheDocument();
    expect(screen.getByText(/9 September 2026/)).toBeInTheDocument();
  });

  it('shows schema, checksum, and the exact artefact download', async () => {
    const fetchMock = vi.fn().mockResolvedValue(response(200, { data: release }));
    vi.stubGlobal('fetch', fetchMock);

    renderRoute('/dataset-releases/2026.09.1');

    expect(await screen.findByRole('heading', { name: 'Dataset 2026.09.1' })).toBeInTheDocument();
    expect(screen.getByText('a'.repeat(64))).toBeInTheDocument();
    const schema = screen.getByRole('heading', { name: 'Schema and fields' }).parentElement!;
    expect(within(schema).getByText('eventId')).toBeInTheDocument();
    expect(
      within(schema).getByText('Stable identifier of the accepted delivery revision.'),
    ).toBeInTheDocument();

    const download = screen.getByRole('link', { name: 'Download JSON artefact' });
    expect(download).toHaveAttribute(
      'href',
      'http://localhost:3000/api/v1/dataset-releases/2026.09.1/artifact.json',
    );
    expect(download).toHaveAttribute('download', 'dataset-release-2026.09.1.json');
    expect(fetchMock).toHaveBeenCalledWith(
      'http://localhost:3000/api/v1/dataset-releases/2026.09.1',
      expect.objectContaining({ headers: { Accept: 'application/json' } }),
    );
  });

  it('presents an unavailable release clearly and supports retry', async () => {
    const fetchMock = vi
      .fn()
      .mockResolvedValueOnce(
        response(404, { error: { code: 'NOT_FOUND', message: 'Dataset release not found.' } }),
      )
      .mockResolvedValueOnce(response(200, { data: release }));
    vi.stubGlobal('fetch', fetchMock);

    renderRoute('/dataset-releases/missing');

    const alert = await screen.findByRole('alert');
    expect(within(alert).getByText('Dataset release not found.')).toBeInTheDocument();
    fireEvent.click(within(alert).getByRole('button', { name: 'Try again' }));

    expect(await screen.findByRole('heading', { name: 'Dataset 2026.09.1' })).toBeInTheDocument();
    await waitFor(() => expect(fetchMock).toHaveBeenCalledTimes(2));
  });
});
