  line-height: 1.6;
}

.browse-page__content {
  display: grid;
  gap: 2rem;
}

.filter-panel {
  padding: 1.5rem;
  border: 1px solid var(--colour-border);
  border-radius: 6px;
  background: var(--colour-surface-raised);
}

.filter-panel__heading,
.results-heading {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1rem;
}

.filter-panel h2,
.results-heading h2,
.related-records h2 {
  max-width: none;
  font-size: 1.5rem;
}

.text-link,
.back-link {
  color: var(--colour-link);
  font-weight: 650;
  text-underline-offset: 0.2em;
}

.filter-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 1rem;
  margin-block: 1.25rem;
}

.field {
  display: grid;
  align-content: start;
  gap: 0.5rem;
  min-width: 0;
}

.field > span,
.field > label {
  color: var(--colour-text-secondary);
  font-size: 0.8125rem;
  font-weight: 650;
}

.field input,
.field select {
  width: 100%;
  min-width: 0;
  min-height: 2.75rem;
  padding: 0.625rem 0.75rem;
  border: 1px solid var(--colour-border);
  border-radius: 6px;
  background: var(--colour-surface);
  color: var(--colour-text);
}

.name-combobox {
  position: relative;
}

.name-combobox__control {
  position: relative;
  display: flex;
}

.name-combobox__control input {
  padding-right: 4.5rem;
}

.name-combobox__clear,
.name-combobox__toggle {
  position: absolute;
  top: 50%;
  min-height: 2rem;
  border: 0;
  background: transparent;
  color: var(--colour-link);
  cursor: pointer;
  transform: translateY(-50%);
}

.name-combobox__clear {
  right: 2rem;
  padding-inline: 0.375rem;
  font-size: 0.75rem;
  font-weight: 650;
}

.name-combobox__toggle {
  right: 0.25rem;
  width: 2rem;
  padding: 0;
  color: var(--colour-text);
}

.name-combobox__clear:focus-visible,
.name-combobox__toggle:focus-visible {
  outline-offset: 0;
}

.name-combobox__popover {
  position: absolute;
  z-index: 20;
  top: calc(100% + 0.25rem);
  right: 0;
  left: 0;
  }

