  }

  .event-export-controls__actions,
  .event-export-controls__actions .button {
    width: 100%;
  }

  .statistic-card,
  .event-trace,
  .statistics-warnings {
    padding: 1.25rem;
  }

  .statistic-metrics,
  .event-trace dl {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .pagination,
  .pagination .button {
    width: 100%;
  }

  .pagination__end {
    text-align: left;
  }

  .detail-page {
    padding-block: 1.5rem 3.5rem;
  }

  .submission-page {
    padding-bottom: 3.5rem;
  }

  .admin-users-page {
    padding-bottom: 3.5rem;
  }

  .submission-form {
    gap: 1.5rem;
  }

  .submission-field textarea {
    min-height: 20rem;
    padding: 0.75rem;
    font-size: 0.8125rem;
  }

  .submission-form > .button {
    width: 100%;
  }

  .correction-workspace {
    margin-top: 2rem;
