        <h1 id="account-page-title">Account</h1>
        {isLoading ? (
          <p role="status">Loading accountâ€¦</p>
        ) : isAuthenticated && identity ? (
          <>
            <dl className="identity-details">
              <div>
                <dt>Email</dt>
                <dd>{identity.email ?? 'Not available'}</dd>
              </div>
            </dl>
            <SubmitterAccessPanel />
            <AccountDeletionForm />
          </>
        ) : (
          <p>
            You are signed out. <Link to="/sign-in">Login or Sign up</Link> to view your account.
          </p>
        )}
      </div>
    </section>
  );
}
import type { Session, SupabaseClient, User } from '@supabase/supabase-js';
import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
  type ReactNode,
} from 'react';

type SupabaseAuthClient = Pick<
  SupabaseClient['auth'],
  'getSession' | 'onAuthStateChange' | 'signInWithOAuth' | 'signOut'
>;

export interface AuthState {
  isLoading: boolean;
  isAuthenticated: boolean;
  session: Session | null;
  identity: User | null;
}

interface AuthContextValue extends AuthState {
  signInWithGoogle: () => Promise<void>;
  signOut: () => Promise<void>;
  clearLocalSession: () => Promise<void>;
}

interface AuthProviderProps {
  children: ReactNode;
